WITH FilteredEmployees AS (SELECT * FROM employees WHERE salary < 78000 AND dept_id IN (4, 8, 21, 34) AND job_title = 'Engineer'), Summary AS (SELECT is_remote, QUARTER(hire_date) AS hire_quarter, MIN(hire_date) AS first_hire_date, MAX(salary) - MIN(salary) AS salary_range FROM FilteredEmployees GROUP BY is_remote, QUARTER(hire_date)) SELECT * FROM Summary ORDER BY first_hire_date DESC;
